import { PureComponent } from 'react'
import { PkgNotFoundStyle, PkgNotFoundCard } from './index.style'
import CustomText from '../../../../../components/CustomText'
import { LANG_STRINGS } from '../../../../../lang'
import { PKG_NOT_FOUND } from '../../../../../images/imageUrl'
import { Button } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

class PkgNotFound extends PureComponent {
  handleBack = () => {
    this.props.history.goBack()
  }

  render () {
    const { image = PKG_NOT_FOUND } = this.props
    return (
      <PkgNotFoundStyle>
        <PkgNotFoundCard>
          <CustomText
            size='38px'
            weight={800}
            bottom='10px'
            color={AgentColorPallette.black}
          >
            {LANG_STRINGS.oops}
          </CustomText>
          <div>
            <img src={image} alt='' />
          </div>
          <CustomText
            size='14px'
            top='20px'
            color={AgentColorPallette.black}
            textAlign='center'
          >
            {this.props.msg || LANG_STRINGS.sorryNoVehiclePkgStatement}
          </CustomText>
        </PkgNotFoundCard>
        <Button onClick={this.handleBack} className='back-btn'>
          {LANG_STRINGS.back}
        </Button>
      </PkgNotFoundStyle>
    )
  }
}

export default PkgNotFound
