import { get } from 'lodash'
import { useCallback } from 'react'
import { DisplayFlexCCC, Row } from '../../../../../../../commonStyle/index.style'
import { Button, CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { getFromLocalStorageData } from '../../../../../../../helpers/localstorage'
import { formatMoney } from '../../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../../lang'
import { MARINE_CARGO_BASIC_DETAILS_FORM } from '../../../../constants'
import { PkgCardStyle } from './index.style'

function PkgCard (props) {
  const { packageItem = {}, history } = props

  const handleThePkgSelect = useCallback(() => {
    // here we are handling the package select
    history.push({
      pathname: `/marine_cargo/${packageItem.code}/package/details`
    })
  }, [history, packageItem.code])

  const shipClass = get(getFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM), 'ship_class', '')

  return (
    <PkgCardStyle>
      <Row className='pkg-name-box' align='center'>
        <DisplayFlexCCC className='package-img-box'>
          <img className='package-img' src={get(packageItem, 'provider.logo_url', '')} alt='package-logo' />
        </DisplayFlexCCC>
        <div>
          {
            shipClass !== 'non-class' &&
              <CustomText
                color={AgentColorPallette.regular}
                size='10px'
                weight={600}
              >
                {get(packageItem, 'provider.name', '')}
              </CustomText>
          }
          <CustomText
            color={AgentColorPallette.regular}
            weight='800'
            size='13px'
          >
            {packageItem.name}
          </CustomText>
        </div>
      </Row>

      <Row justify='space-between' className='amount-section'>
        <div>
          <CustomText
            size='15px'
            color={AgentColorPallette.black}
            weight={700}
          >
            {formatMoney(get(packageItem, 'premium.amount', 0), 0)}
          </CustomText>
          <CustomText
            size='10px'
            color={AgentColorPallette.fontDarkerGrey}
            weight={600}
          >
            {LANG_STRINGS.marineCargoPeriod}
          </CustomText>
        </div>
        {
          !!packageItem.points &&
            <div>
              <CustomText
                size='10px'
                color={AgentColorPallette.fontDarkerGrey}
                weight={700}
              >
                {LANG_STRINGS.pointsSmall}
              </CustomText>
              <CustomText
                size='13px'
                color={AgentColorPallette.regular}
                weight={600}
              >
                {get(packageItem, 'points', '0')}
              </CustomText>
            </div>
        }
      </Row>
      <Button
        textColor={AgentColorPallette.madras}
        onClick={handleThePkgSelect}
        className='pkg-select-btn'
        color={AgentColorPallette.darkerGold}
        id={`cargoPkgSelect-${packageItem.code}`}
      >
        {LANG_STRINGS.buyPackage}
      </Button>
    </PkgCardStyle>
  )
}

export default PkgCard
