import size from 'lodash/size'
import { Container, CustomText } from '../../../../../../components'
import StepsHeader from '../../../../../../components/StepsHeader'
import PkgNotFound from '../../../../Application/components/PkgNotFound'
import { PackagesStyle } from './index.style'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import { useGetPackages } from '../../../state/hooks/useMarineCargo'
import { useEffect } from 'react'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { LANG_STRINGS } from '../../../../../../lang'
import { getFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { MARINE_CARGO_BASIC_DETAILS_FORM } from '../../../constants'
import { MARINE_CARGO_PROTECTION } from '../../../../../../constants/pkgCode'
import PkgCard from '../components/pkgCard'
import get from 'lodash/get'
import { PKG_NOT_FOUND_CARGO } from '../../../../../../images'

function MarineCargoPackages (props) {
  const { history } = props
  const [{ GET_PACKAGES_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getPackagesData = [] }, getPackagesRequest] = useGetPackages()
  const [
    {
      GET_PACKAGES_ERROR, getPackagesStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (GET_PACKAGES_LOADER === undefined) {
      const formDetails = getFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM)
      getPackagesRequest({ body: { ...formDetails, package_type: MARINE_CARGO_PROTECTION } })
    }
  }, [getPackagesRequest, GET_PACKAGES_LOADER])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PACKAGES_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_PACKAGES_ERROR && getPackagesStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getPackagesStatus
      })
      dispatchError(resetError({
        getPackagesStatus: ''
      }))
    }
  }, [GET_PACKAGES_ERROR, getPackagesStatus,
    dispatchError
  ])

  const packages = get(getPackagesData, 'complete_match', [])

  return (
    <Container
      title='Kargo'
      hideBottomTabs
      displayBackButton
      backBtnId='kargoStepBack_2'
      loader={GET_PACKAGES_LOADER}
    >
      <PackagesStyle>
        <div className='steps-header-container'>
          <StepsHeader leftText='Paket Asuransi' current='2' totalSteps='4' />
        </div>
        <CustomText
          textAlign='center'
          size='10px'
          className='info-chip'
          weight={700}
        >
          {LANG_STRINGS.maximumBonusForMarineCargo}
        </CustomText>
        <div className='content'>
          {
            !!((size(packages) && !GET_PACKAGES_LOADER)) && (
              <div className='pkgs-container'>
                {
                  packages.map(pkg => (
                    <PkgCard history={history} key={pkg.code} packageItem={pkg} />
                  ))
                }
              </div>
            )
          }
          {
            !size(packages) && !GET_PACKAGES_LOADER && (
              <PkgNotFound
                image={PKG_NOT_FOUND_CARGO}
                history={props.history}
                msg={LANG_STRINGS.pkgNotExistCargo}
              />
            )
          }
        </div>
        <ShowSnackbar hideOkay />
      </PackagesStyle>
    </Container>
  )
}

export default MarineCargoPackages
